async function mqttSubscribe({host, port, topic, clientId}) {
  const connectPacket = await renderConnect({
    protoName: 'MQTT',
    protoLevel: 4,
    connectFlags: { cleanSession: true },
    keepAlive: 60,
    clientId
  });

  const subscribePacket = await renderSubscribe({
    packetId: 1,
    subscriptions: [{ topic, qos: 1 }]
  });

  return new Promise((resolve, reject) => {
    const socket = net.connect({host, port}, () => {
      socket.write(Buffer.from(connectPacket.bytes));
      socket.write(Buffer.from(subscribePacket.bytes), () => {
        resolve();
      });
    });

    socket.on('error', reject);
  });
}

async function mqttSubscribe({host, port, topic, clientId}) {
  const connectPacket = await renderConnect({
    protoName: 'MQTT',
    protoLevel: 4,
    connectFlags: { cleanSession: true },
    keepAlive: 60,
    clientId
  });

  const subscribePacket = await renderSubscribe({
    packetId: 1,
    subscriptions: [{ topic, qos: 1 }]
  });

  return new Promise((resolve, reject) => {
    const socket = net.connect({host, port}, () => {
      socket.write(Buffer.from(connectPacket.bytes), (err) => {
        if (err) return reject(err);
        socket.write(Buffer.from(subscribePacket.bytes), (err) => {
          if (err) return reject(err);
          resolve();
        });
      });
    });

    socket.on('error', reject);
  });
}

function mqttSubscribe({host, port, topic, clientId}) {
  return new Promise(async (resolve, reject) => {
    const connectPacket = await renderConnect({
      protoName: 'MQTT',
      protoLevel: 4,
      connectFlags: { cleanSession: true },
      keepAlive: 60,
      clientId
    });

    const subscribePacket = await renderSubscribe({
      packetId: 1,
      subscriptions: [{ topic, qos: 1 }]
    });

    const socket = net.connect({host, port}, () => {
      socket.write(Buffer.from(connectPacket.bytes), () => {
        socket.write(Buffer.from(subscribePacket.bytes), () => {
          resolve();
        });
      });
    });

    socket.on('error', reject);
  });
}
